"use client"

// From chatcn, chat, voice and agent UI for shadcn: https://chatcn.dev

import * as React from "react"
import { forwardRef, createElement, type SVGAttributes, type ForwardRefExoticComponent, type RefAttributes } from "react"
import { cn } from "@/lib/utils"
import { createPortal } from "react-dom"

/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-bg:oklch(1 0 0);--chatcn-border-strong:var(--chatcn-gray-600);--chatcn-card:oklch(1 0 0);--chatcn-ease-out:cubic-bezier(0.23, 1, 0.32, 1);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-600:oklch(0.800 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-radius-lg:12px;--chatcn-radius-md:8px;--chatcn-radius-xl:16px;--chatcn-red:oklch(0.560 0.200 27);--chatcn-shadow-sm:0 0 0 1px oklch(0 0 0 / 0.06), 0 1px 2px -1px oklch(0 0 0 / 0.06), 0 2px 4px oklch(0 0 0 / 0.04)}.dark{--chatcn-bg:oklch(0.145 0 0);--chatcn-border-strong:var(--chatcn-gray-600);--chatcn-card:oklch(0.175 0 0);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-600:oklch(0.410 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-red:oklch(0.700 0.175 22);--chatcn-shadow-sm:0 0 0 1px oklch(1 0 0 / 0.08), inset 0 1px 0 oklch(1 0 0 / 0.03), 0 2px 4px oklch(0 0 0 / 0.4)}"
if (typeof document !== "undefined" && !document.getElementById("chatcn-drop-zone")) {
  const style = document.createElement("style")
  style.id = "chatcn-drop-zone"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const KINDS: [RegExp, string][] = [
  [/^image\/\*$/, "images"],
  [/^(\.pdf|application\/pdf)$/, "PDFs"],
  [/^video\/\*$/, "videos"],
  [/^audio\/\*$/, "audio"],
  [/^text\/\*$/, "text files"],
  [/^(\.csv|text\/csv)$/, "CSV files"],
  [/^(\.md|text\/markdown)$/, "Markdown files"],
  [/^(\.txt|text\/plain)$/, "text files"],
  [/^(\.json|application\/json)$/, "JSON files"],
]

function joinWords(words: string[]) {
  if (words.length <= 1) return words[0] ?? ""
  return `${words.slice(0, -1).join(", ")} and ${words[words.length - 1]}`
}

/** Readable list from an accept string: `image/*,.pdf` becomes "images and PDFs". */
export function describeAccept(accept?: string) {
  if (!accept) return ""
  const words: string[] = []
  for (const raw of accept.split(",")) {
    const rule = raw.trim().toLowerCase()
    if (!rule) continue
    const kind =
      KINDS.find(([re]) => re.test(rule))?.[1] ??
      (rule.startsWith(".") ? `${rule.slice(1).toUpperCase()} files` : rule)
    if (!words.includes(kind)) words.push(kind)
  }
  return joinWords(words)
}

export interface FileRejection {
  file: File
  reason: "type" | "size" | "count"
}

interface UseChatcnFileDropOptions {
  /** Same syntax as `<input accept>`: `image/*,.pdf,application/json`. Empty accepts anything. */
  accept?: string
  /** Largest file in bytes. */
  maxSize?: number
  /** Most files in one drop. */
  maxFiles?: number
  disabled?: boolean
  onFiles?: (files: File[]) => void
  onReject?: (rejections: FileRejection[]) => void
  /**
   * `element` (default): spread `rootProps` on the drop target.
   * `window`: listen on the whole page, for a full-page overlay.
   */
  target?: "element" | "window"
}

/* -------------------------------------------------------------------------------------------------
 * DropZonePage
 * -----------------------------------------------------------------------------------------------*/

export interface DropZonePageProps extends Omit<UseChatcnFileDropOptions, "target"> {
  label?: React.ReactNode
  hint?: React.ReactNode
  rejectLabel?: React.ReactNode
  className?: string
}

type DropState = "idle" | "accept" | "reject"

function hasFiles(event: DragEvent | React.DragEvent) {
  return Array.from(event.dataTransfer?.types ?? []).includes("Files")
}

/** Extensions mapped to MIME types, so `.pdf` can be judged while dragging, before names exist. */
const EXT_MIME: Record<string, string> = {
  ".pdf": "application/pdf",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".webp": "image/webp",
  ".svg": "image/svg+xml",
  ".csv": "text/csv",
  ".txt": "text/plain",
  ".md": "text/markdown",
  ".json": "application/json",
  ".zip": "application/zip",
}

/**
 * Whether a file (or a dragged item, which has a type but no name yet) matches an accept string.
 * Unknown types pass while dragging and are judged again by name on drop.
 */
function matchesAccept(file: { type: string; name?: string }, accept?: string) {
  if (!accept) return true
  const rules = accept
    .split(",")
    .map((r) => r.trim().toLowerCase())
    .filter(Boolean)
  if (rules.length === 0) return true
  const type = file.type.toLowerCase()
  const name = file.name?.toLowerCase()
  if (!type && !name) return true
  return rules.some((rule) => {
    if (rule.startsWith(".")) {
      if (name) return name.endsWith(rule)
      return EXT_MIME[rule] === type
    }
    if (rule.endsWith("/*")) return type.startsWith(rule.slice(0, -1))
    return type === rule
  })
}

/** Judges the drag from what the browser exposes before the drop: item kinds and MIME types. */
function judgeDrag(event: DragEvent | React.DragEvent, accept?: string, maxFiles?: number) {
  const items = Array.from(event.dataTransfer?.items ?? []).filter((i) => i.kind === "file")
  if (maxFiles !== undefined && items.length > maxFiles) return "reject" as const
  return items.every((i) => matchesAccept({ type: i.type }, accept)) ? "accept" : "reject"
}

/** Splits dropped or pasted files into accepted and rejected, with a reason for each rejection. */
function sortFiles(
  files: File[],
  { accept, maxSize, maxFiles }: Pick<UseChatcnFileDropOptions, "accept" | "maxSize" | "maxFiles">,
) {
  const accepted: File[] = []
  const rejected: FileRejection[] = []
  for (const file of files) {
    if (!matchesAccept(file, accept)) rejected.push({ file, reason: "type" })
    else if (maxSize !== undefined && file.size > maxSize) rejected.push({ file, reason: "size" })
    else if (maxFiles !== undefined && accepted.length >= maxFiles)
      rejected.push({ file, reason: "count" })
    else accepted.push(file)
  }
  return { accepted, rejected }
}

/**
 * Drag and drop for files. Tracks whether files are over the target and whether they would be
 * accepted, so the overlay can say so before the drop. Text drags pass through untouched, so
 * dragging a snippet into a textarea still works.
 */
function useChatcnFileDrop(options: UseChatcnFileDropOptions = {}) {
  const optionsRef = React.useRef(options)
  optionsRef.current = options
  const [state, setState] = React.useState<DropState>("idle")
  const depth = React.useRef(0)

  const handlers = React.useMemo(() => {
    const enter = (event: DragEvent | React.DragEvent) => {
      const { disabled, accept, maxFiles } = optionsRef.current
      if (disabled || !hasFiles(event)) return
      event.preventDefault()
      depth.current += 1
      setState(judgeDrag(event, accept, maxFiles))
    }
    const over = (event: DragEvent | React.DragEvent) => {
      if (optionsRef.current.disabled || !hasFiles(event)) return
      event.preventDefault()
      if (event.dataTransfer) event.dataTransfer.dropEffect = "copy"
    }
    const leave = (event: DragEvent | React.DragEvent) => {
      if (optionsRef.current.disabled || !hasFiles(event)) return
      depth.current = Math.max(0, depth.current - 1)
      if (depth.current === 0) setState("idle")
    }
    const drop = (event: DragEvent | React.DragEvent) => {
      const { disabled, onFiles, onReject } = optionsRef.current
      if (disabled || !hasFiles(event)) return
      event.preventDefault()
      depth.current = 0
      setState("idle")
      const files = Array.from(event.dataTransfer?.files ?? [])
      const { accepted, rejected } = sortFiles(files, optionsRef.current)
      if (accepted.length) onFiles?.(accepted)
      if (rejected.length) onReject?.(rejected)
    }
    return { enter, over, leave, drop }
  }, [])

  const target = options.target ?? "element"
  React.useEffect(() => {
    if (target !== "window") return
    const { enter, over, leave, drop } = handlers
    window.addEventListener("dragenter", enter)
    window.addEventListener("dragover", over)
    window.addEventListener("dragleave", leave)
    window.addEventListener("drop", drop)
    return () => {
      window.removeEventListener("dragenter", enter)
      window.removeEventListener("dragover", over)
      window.removeEventListener("dragleave", leave)
      window.removeEventListener("drop", drop)
    }
  }, [target, handlers])

  React.useEffect(() => {
    if (options.disabled) {
      depth.current = 0
      setState("idle")
    }
  }, [options.disabled])

  const rootProps = React.useMemo(
    () => ({
      onDragEnter: handlers.enter as (event: React.DragEvent) => void,
      onDragOver: handlers.over as (event: React.DragEvent) => void,
      onDragLeave: handlers.leave as (event: React.DragEvent) => void,
      onDrop: handlers.drop as (event: React.DragEvent) => void,
    }),
    [handlers],
  )

  return { state, rootProps }
}

/** How many files a drag carries. Browsers expose the items, not the files, until the drop. */
function countDragFiles(event: DragEvent | React.DragEvent) {
  return Array.from(event.dataTransfer?.items ?? []).filter((i) => i.kind === "file").length
}

/* -------------------------------------------------------------------------------------------------
 * Overlay
 * -----------------------------------------------------------------------------------------------*/

export interface DropZoneOverlayProps extends React.ComponentProps<"div"> {
  state: DropState
  /** Accept title. Default "Drop files to attach". */
  label?: React.ReactNode
  /** Second line under the title, for example the accepted types and size limit. */
  hint?: React.ReactNode
  /** Reject title. Default says which types are accepted, built from `accept`. */
  rejectLabel?: React.ReactNode
  accept?: string
  /** Files in the drag, so the default copy can count them: "Drop 3 files to attach". */
  count?: number
  /** The most files one drop takes. With `count` above it, the reject copy says so. */
  maxFiles?: number
  /** `contained` fills its positioned parent; `page` covers the viewport. */
  variant?: "contained" | "page"
}

function capitalize(text: string) {
  return text.charAt(0).toUpperCase() + text.slice(1)
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
  ["path", {"d":"M3 12a9 9 0 1 0 18 0 9 9 0 1 0-18 0"}],
  ["path", {"d":"m7.76 7.76 8.48 8.48"}],
]

const BanIcon: Icon = /* @__PURE__ */ createIcon("ban", iconNode)

const iconNode2: IconNode = [
  ["path", {"d":"M3.5 15v2.5a3 3 0 0 0 3 3h11a3 3 0 0 0 3-3V15"}],
  ["path", {"d":"m16.5 8-3.09-3.09a2 2 0 0 0-2.82 0L7.5 8"}],
  ["path", {"d":"M12 15.5V8"}],
]

export const UploadIcon: Icon = /* @__PURE__ */ createIcon("upload", iconNode2)

/**
 * What the user sees while dragging files. Fades in over 150 ms with the content settling from
 * scale 0.98; says before the drop what will happen, counted ("Drop 3 files to attach"), or that
 * the files will be refused, and why: the wrong type, or more than one drop takes.
 */
export function DropZoneOverlay({
  state,
  label,
  hint,
  rejectLabel,
  accept,
  count,
  maxFiles,
  variant = "contained",
  className,
  ...props
}: DropZoneOverlayProps) {
  const visible = state !== "idle"
  const reject = state === "reject"
  const types = describeAccept(accept)
  const page = variant === "page"
  const tooMany = count !== undefined && maxFiles !== undefined && count > maxFiles
  const what = !count ? "files" : count === 1 ? "the file" : `${count.toLocaleString()} files`
  const title = reject
    ? (rejectLabel ??
      (tooMany
        ? `Attach up to ${maxFiles} ${maxFiles === 1 ? "file" : "files"} at a time`
        : types
          ? `Only ${types} can be attached`
          : "These files can’t be attached"))
    : (label ?? `Drop ${what} ${page ? "anywhere " : ""}to attach`)
  const sub = reject
    ? tooMany && !rejectLabel
      ? `You’re dragging ${count?.toLocaleString()}.`
      : null
    : (hint ?? (types ? capitalize(types) : null))

  return (
    <div
      aria-hidden="true"
      data-slot="drop-zone-overlay"
      data-drop-state={state}
      data-variant={variant}
      className={cn(
        "pointer-events-none grid place-items-center",
        page ? "fixed inset-0 z-50 p-3" : "absolute inset-0 z-10 rounded-[inherit] p-2",
        page
          ? "bg-[color-mix(in_oklch,var(--chatcn-bg)_88%,transparent)]"
          : "bg-[color-mix(in_oklch,var(--chatcn-card)_94%,transparent)]",
        "ease-(--chatcn-ease-out) transition-[opacity,visibility] duration-150 motion-reduce:duration-100",
        visible ? "visible opacity-100" : "invisible opacity-0",
        className,
      )}
      {...props}
    >
      <div
        className={cn(
          "border-(color:--chatcn-border-strong) grid size-full place-items-center border border-dashed",
          // Concentric: 12 px inset plus 12 px radius fits a 24 px window corner; 8 plus 8 fits 16.
          page ? "rounded-(--chatcn-radius-lg) border-2" : "rounded-(--chatcn-radius-md)",
          reject && "border-solid",
        )}
      >
        <div
          className={cn(
            "flex flex-col items-center gap-1.5 px-4 text-center",
            "ease-(--chatcn-ease-out) transition-[scale] duration-150 motion-reduce:scale-none!",
            visible ? "scale-100" : "scale-98",
          )}
        >
          <span
            key={reject ? "reject" : "accept"}
            className={cn(
              "grid place-items-center motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]",
              page ? "mb-1 [&_svg]:size-6" : "[&_svg]:size-5",
              reject ? "text-(color:--chatcn-red)" : "text-(color:--chatcn-fg)",
            )}
          >
            {reject ? <BanIcon /> : <UploadIcon />}
          </span>
          <p
            className={cn(
              "text-(color:--chatcn-fg) font-medium text-balance!",
              page ? "text-[1.25rem]/[1.75rem] tracking-[-0.018em]" : "text-[0.875rem]/[1.25rem] tracking-[-0.003em]",
            )}
          >
            {title}
          </p>
          {sub ? (
            <p
              className={cn(
                "text-(color:--chatcn-fg-subtle) tabular-nums",
                page ? "text-[0.875rem]/[1.25rem] tracking-[-0.003em]" : "text-[0.8125rem]/[1.25rem]",
              )}
            >
              {sub}
            </p>
          ) : null}
        </div>
      </div>
    </div>
  )
}

/** Listens on the whole window and covers the page while files are dragged anywhere over it. */
export function DropZonePage({ label, hint, rejectLabel, className, ...options }: DropZonePageProps) {
  const { state } = useChatcnFileDrop({ ...options, target: "window" })
  const [mounted, setMounted] = React.useState(false)
  const [count, setCount] = React.useState<number>()
  React.useEffect(() => setMounted(true), [])
  React.useEffect(() => {
    const enter = (event: DragEvent) => setCount(countDragFiles(event) || undefined)
    window.addEventListener("dragenter", enter)
    return () => window.removeEventListener("dragenter", enter)
  }, [])
  if (!mounted) return null
  return createPortal(
    <DropZoneOverlay
      variant="page"
      state={state}
      accept={options.accept}
      count={count}
      maxFiles={options.maxFiles}
      label={label}
      hint={hint}
      rejectLabel={rejectLabel}
      className={className}
    />,
    document.body,
  )
}

/* -------------------------------------------------------------------------------------------------
 * DropZone
 * -----------------------------------------------------------------------------------------------*/

export interface DropZoneProps
  extends Omit<React.ComponentProps<"div">, "onDrop">,
    Omit<UseChatcnFileDropOptions, "target"> {
  label?: React.ReactNode
  hint?: React.ReactNode
  rejectLabel?: React.ReactNode
}

/**
 * A drop target the size of its content, such as a composer. Wrap the area and the overlay
 * appears inside it, following its corner radius. Pair it with an attach button: dragging is
 * never the only way in.
 */
export function DropZone({
  accept,
  maxSize,
  maxFiles,
  disabled,
  onFiles,
  onReject,
  label,
  hint,
  rejectLabel,
  className,
  children,
  ...props
}: DropZoneProps) {
  const { state, rootProps } = useChatcnFileDrop({
    accept,
    maxSize,
    maxFiles,
    disabled,
    onFiles,
    onReject,
  })
  const [count, setCount] = React.useState<number>()
  // Count the files on the way in, so the overlay can say what one drop will do.
  const dropProps = {
    ...rootProps,
    onDragEnter: (event: React.DragEvent) => {
      rootProps.onDragEnter(event)
      setCount(countDragFiles(event) || undefined)
    },
  }
  return (
    <div
      data-slot="drop-zone"
      data-drop-state={state}
      className={cn("relative", className)}
      {...dropProps}
      {...props}
    >
      {children}
      <DropZoneOverlay
        state={state}
        accept={accept}
        count={count}
        maxFiles={maxFiles}
        label={label}
        hint={hint}
        rejectLabel={rejectLabel}
      />
    </div>
  )
}

export default DropZone

